// Regenerates the frozen v1 artifact src/compat/location-picker.min.js from src/compat/v1.ts
// (AMENDMENTS A1): a tsdown UMD build (ES2015 syntax level, unminified), then a terser ES5 pass.
// `npm run build` never runs this; it only copies the committed artifact into dist/.
//
//   node scripts/minify-v1.mjs           rewrite the artifact
//   node scripts/minify-v1.mjs --check   fail if the regenerated bytes differ from the committed artifact
import { createHash } from 'node:crypto';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { brotliCompressSync } from 'node:zlib';
import { parse } from 'acorn';
import { minify } from 'terser';
import { build } from 'tsdown';

const ARTIFACT = 'src/compat/location-picker.min.js';
const check = process.argv.includes('--check');

const outDir = await mkdtemp(join(tmpdir(), 'lp-v1-'));
try {
  await build({
    config: false,
    logLevel: 'warn',
    entry: { 'location-picker.min': 'src/compat/v1.ts' },
    format: 'umd',
    globalName: 'locationPicker',
    platform: 'browser',
    target: 'es2015',
    minify: false,
    dts: false,
    outDir,
    outputOptions: { exports: 'default', entryFileNames: 'location-picker.min.js' },
  });
  const umd = await readFile(join(outDir, 'location-picker.min.js'), 'utf8');
  const out = await minify(umd, {
    ecma: 5,
    compress: { ecma: 5, passes: 2 },
    mangle: true,
    format: { ecma: 5, comments: false },
  });
  const code = `${out.code}\n`;
  parse(code, { ecmaVersion: 5 });

  const sha = createHash('sha256').update(code).digest('hex');
  const brotli = brotliCompressSync(Buffer.from(code)).length;
  console.log(`v1: ${Buffer.byteLength(code)} B, ${brotli} B brotli, sha256 ${sha}`);

  if (check) {
    const committed = await readFile(ARTIFACT, 'utf8');
    if (committed !== code) {
      console.error(
        `${ARTIFACT} is out of sync with src/compat/v1.ts (or the toolchain changed its output).\n` +
          'Run `npm run build:v1` and commit the artifact with [v1-change] in the message.',
      );
      process.exitCode = 1;
    }
  } else {
    await writeFile(ARTIFACT, code);
  }
} finally {
  await rm(outDir, { recursive: true, force: true });
}
